"use client";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import Modal from "./Modal";
import Input from "./ui/Input";
import SegmentedControl from "./ui/SegmentedControl";
import SearchSelect from "./ui/SearchSelect";
import { useEffect } from "react";

const couponSchema = z.object({
    code: z.string().min(3, "Código deve ter pelo menos 3 caracteres").toUpperCase(),
    discountType: z.enum(["percent", "fixed"]),
    discountValue: z.string().min(1, "Informe o valor"),
    influencer: z.string().min(1, "Informe o influenciador"),
    products: z.string().optional(),
});

type CouponFormData = z.infer<typeof couponSchema>;

interface CouponModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: CouponFormData) => void;
    initialData?: any;
    title: string;
}

export default function CouponModal({ isOpen, onClose, onSubmit, initialData, title }: CouponModalProps) {
    const {
        register,
        handleSubmit,
        reset,
        watch,
        setValue,
        formState: { errors, isSubmitting }
    } = useForm<CouponFormData>({
        resolver: zodResolver(couponSchema),
    });

    useEffect(() => {
        if (initialData) {
            // Transform legacy data if needed
            reset({
                code: initialData.code || "",
                discountType: initialData.discount?.includes("%") ? "percent" : "fixed",
                discountValue: initialData.discount?.replace(/[^0-9]/g, "") || "",
                influencer: initialData.influencer || "Geral",
                products: initialData.products || "Todos",
            });
        } else {
            reset({ code: "", discountType: "percent", discountValue: "", influencer: "Geral", products: "Todos" });
        }
    }, [initialData, reset, isOpen]);

    const discountType = watch("discountType");

    const onSubmitProxy = (data: any) => {
        const formattedData = {
            ...data,
            discount: data.discountType === "percent" ? `${data.discountValue}%` : `R$ ${data.discountValue}`,
        };
        onSubmit(formattedData);
    };

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={title}>
            <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                <Input
                    label="Código do Cupom"
                    {...register("code")}
                    error={errors.code?.message}
                    placeholder="Ex: VERAO2026"
                />

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <Input
                        label="Valor do Desconto"
                        {...register("discount")}
                        error={errors.discount?.message}
                        placeholder="Ex: 15% ou R$ 50,00"
                    />
                    <Input
                        label="Influenciador / Origem"
                        {...register("influencer")}
                        error={errors.influencer?.message}
                        placeholder="Ex: @vlog_contabil"
                    />
                </div>

                <Input
                    label="Produtos Aplicáveis"
                    {...register("products")}
                    error={errors.products?.message}
                    placeholder="Ex: Todos, Apenas A1, etc."
                />

                <div className="flex justify-end gap-3 pt-4">
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-6 py-3 rounded-2xl font-bold text-xs text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all"
                    >
                        Cancelar
                    </button>
                    <button
                        type="submit"
                        disabled={isSubmitting}
                        className="bg-primary text-white px-8 py-3 rounded-2xl font-bold text-xs shadow-xl shadow-primary/20 hover:scale-[1.02] transition-all disabled:opacity-50"
                    >
                        {isSubmitting ? "Salvando..." : "Salvar Cupom"}
                    </button>
                </div>
            </form>
        </Modal>
    );
}
